@sealed
class ApiWalletImpl extends RustOpaque implements ApiWallet {
  // Not to be used by end users
  ApiWalletImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  ApiWalletImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_ApiWallet,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_ApiWallet,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_ApiWalletPtr,
  );

  /// Import a mnemonic phrase as a signing key. Validates the words, computes
  /// the MFP, and stores the seed in the encrypted wallet database.
  APIHotKeyInfo addMnemonicKey({
    required String mnemonic,
    String? passphrase,
  }) => RustLib.instance.api.crateApiWalletApiWalletAddMnemonicKey(
    that: this,
    mnemonic: mnemonic,
    passphrase: passphrase,
  );

  /// Import a master xprv (depth=0 only) as a signing key.
  APIHotKeyInfo addXprvKey({required String xprv}) => RustLib.instance.api
      .crateApiWalletApiWalletAddXprvKey(that: this, xprv: xprv);

  /// Analyze partial signatures present in a PSBT.
  ///
  /// Returns signing status per MFP (must sign every input to count as signed)
  /// and whether all inputs are already finalized.
  Future<APIPsbtAnalysis> analyzePsbt({
    required String psbtBase64,
    required List<String> mfps,
  }) => RustLib.instance.api.crateApiWalletApiWalletAnalyzePsbt(
    that: this,
    psbtBase64: psbtBase64,
    mfps: mfps,
  );

  String get path => RustLib.instance.api
      .crateApiWalletApiWalletAutoAccessorGetPath(that: this);

  set path(String path) => RustLib.instance.api
      .crateApiWalletApiWalletAutoAccessorSetPath(that: this, path: path);

  /// Finalize the PSBT, broadcast via Electrum, and delete the local record.
  ///
  /// Returns the broadcast txid on success.
  Future<String> broadcastPsbt({
    required PlatformInt64 id,
    required String electrumUrl,
  }) => RustLib.instance.api.crateApiWalletApiWalletBroadcastPsbt(
    that: this,
    id: id,
    electrumUrl: electrumUrl,
  );

  /// Change the wallet's encryption protection scheme.
  ///
  /// Generates a fresh SQLCipher data key and re-encrypts the database
  /// in-place via `PRAGMA rekey` — the existing connection stays open and
  /// operational throughout. The `.meta` sidecar is then rewritten with the
  /// new scheme. No export/import required.
  ///
  /// After this call the Dart layer must update its credential cache:
  /// - `DeviceKey` → evict any cached password (automatic unlock).
  /// - `UserPassword` → cache `new_password`.
  /// - `XpubKey` → evict any cached password (user enters xpub on next open).
  Future<void> changeProtection({
    required String deviceKeyHex,
    required APIProtectionType newProtectionType,
    String? newPassword,
    required APISecurityLevel securityLevel,
  }) => RustLib.instance.api.crateApiWalletApiWalletChangeProtection(
    that: this,
    deviceKeyHex: deviceKeyHex,
    newProtectionType: newProtectionType,
    newPassword: newPassword,
    securityLevel: securityLevel,
  );

  /// Delete all stored fiat prices (called when the user changes fiat currency).
  Future<void> clearFiatPrices() =>
      RustLib.instance.api.crateApiWalletApiWalletClearFiatPrices(that: this);

  /// Build an unsigned PSBT with optional coin control and spend-path selection.
  ///
  /// * `selected_utxos` — if non-empty, only those coins are used.
  ///   Empty = BDK automatic coin selection.
  /// * `policy_path`    — spend-path branch selections from [APISpendPath.policyPath].
  /// * `spend_path_id`  — rust_id of the selected spend path (stored for reference).
  /// * `threshold`      — required signatures (from the spend path).
  /// * `mfps`           — master fingerprints of keys in the spend path.
  APIPsbtInfo createPsbt({
    required String recipientAddress,
    required BigInt amountSat,
    required double feeRateSatPerVb,
    required List<APICoinControl> selectedUtxos,
    required List<APIPolicyPath> policyPath,
    required int spendPathId,
    required int threshold,
    required List<String> mfps,
    required bool sendMax,
  }) => RustLib.instance.api.crateApiWalletApiWalletCreatePsbt(
    that: this,
    recipientAddress: recipientAddress,
    amountSat: amountSat,
    feeRateSatPerVb: feeRateSatPerVb,
    selectedUtxos: selectedUtxos,
    policyPath: policyPath,
    spendPathId: spendPathId,
    threshold: threshold,
    mfps: mfps,
    sendMax: sendMax,
  );

  /// Remove a hot signing key by MFP.
  void deleteHotKey({required String mfp}) => RustLib.instance.api
      .crateApiWalletApiWalletDeleteHotKey(that: this, mfp: mfp);

  /// Delete a saved PSBT by id.
  void deletePsbt({required PlatformInt64 id}) => RustLib.instance.api
      .crateApiWalletApiWalletDeletePsbt(that: this, id: id);

  /// Export all explicit (non-auto) labels to BIP-329 JSONL format.
  List<String> exportBip329() =>
      RustLib.instance.api.crateApiWalletApiWalletExportBip329(that: this);

  /// Return full detail for an address: the address plus its unspent UTXOs.
  Future<APIAddressDetails> getAddressDetails({required String address}) =>
      RustLib.instance.api.crateApiWalletApiWalletGetAddressDetails(
        that: this,
        address: address,
      );

  /// Return all currently revealed addresses for the given keychain, sorted by index ascending.
  /// Balance is the sum of all unspent outputs currently controlled by each address.
  Future<List<APIAddress>> getAddresses({required APIKeychain keychain}) =>
      RustLib.instance.api.crateApiWalletApiWalletGetAddresses(
        that: this,
        keychain: keychain,
      );

  /// Return the cached balance (no network call).
  Future<APIBalance> getBalance() =>
      RustLib.instance.api.crateApiWalletApiWalletGetBalance(that: this);

  /// Return all stored BTC prices for `currency` as a list of (txid, price) pairs.
  Future<List<APIFiatPrice>> getFiatPrices({required String currency}) =>
      RustLib.instance.api.crateApiWalletApiWalletGetFiatPrices(
        that: this,
        currency: currency,
      );

  /// Read wallet metadata from the open connection (no file re-open).
  Future<APIWalletInfo> getInfo() =>
      RustLib.instance.api.crateApiWalletApiWalletGetInfo(that: this);

  /// Return all key labels (mfp → label).
  Future<List<APIKeyLabel>> getKeyLabels() =>
      RustLib.instance.api.crateApiWalletApiWalletGetKeyLabels(that: this);

  /// Return all spend-path labels (rust_id → label).
  Future<List<APIPathLabel>> getPathLabels() =>
      RustLib.instance.api.crateApiWalletApiWalletGetPathLabels(that: this);

  /// Return RBF replacement constraints for a mempool tx spending one of our UTXOs.
  /// Fetches parent txs from Electrum when fee cannot be determined from the wallet graph.
  Future<APIRbfInfo> getRbfInfo({required String spendingTxid}) =>
      RustLib.instance.api.crateApiWalletApiWalletGetRbfInfo(
        that: this,
        spendingTxid: spendingTxid,
      );

  /// Return the current best block height from the local chain (0 if not yet synced).
  Future<int> getTipHeight() =>
      RustLib.instance.api.crateApiWalletApiWalletGetTipHeight(that: this);

  /// Return a paginated page of transactions, sorted newest-first (no network call).
  Future<APITransactionPage> getTransactions({
    required int page,
    required int pageSize,
  }) => RustLib.instance.api.crateApiWalletApiWalletGetTransactions(
    that: this,
    page: page,
    pageSize: pageSize,
  );

  /// Return full detail for a transaction: the tx plus related UTXOs, input addresses,
  /// and output addresses. External input transactions not in BDK's graph are fetched
  /// from Electrum (using the URL stored from the last sync).
  Future<APITxDetails> getTxDetails({required String txid}) => RustLib
      .instance
      .api
      .crateApiWalletApiWalletGetTxDetails(that: this, txid: txid);

  /// Return transactions that have no stored fiat price for `currency`.
  Future<List<APITxMissingFiat>> getTxidsMissingFiat({
    required String currency,
  }) => RustLib.instance.api.crateApiWalletApiWalletGetTxidsMissingFiat(
    that: this,
    currency: currency,
  );

  /// Return full detail for a UTXO: the UTXO plus the explicit labels of its cluster peers.
  Future<APIUtxoDetails> getUtxoDetails({
    required String txid,
    required int vout,
  }) => RustLib.instance.api.crateApiWalletApiWalletGetUtxoDetails(
    that: this,
    txid: txid,
    vout: vout,
  );

  /// Return all unspent outputs (UTXOs / coins), sorted by value descending.
  Future<List<APIUtxo>> getUtxos() =>
      RustLib.instance.api.crateApiWalletApiWalletGetUtxos(that: this);

  /// Import labels from BIP-329 JSONL. Sets all as explicit, then re-propagates.
  /// Malformed lines and unknown types are silently skipped.
  void importBip329({required List<String> lines}) => RustLib.instance.api
      .crateApiWalletApiWalletImportBip329(that: this, lines: lines);

  /// Import a PSBT (base64) from an external source.
  ///
  /// If a record with the same unsigned txid already exists, the signatures are
  /// merged and the existing record is updated (`was_merged = true`).
  /// Otherwise a new record is created with metadata extracted from the PSBT.
  Future<APIImportPsbtResult> importPsbt({required String psbtBase64}) =>
      RustLib.instance.api.crateApiWalletApiWalletImportPsbt(
        that: this,
        psbtBase64: psbtBase64,
      );

  /// List all hot signing keys stored in this wallet (never exposes the seed).
  List<APIHotKeyInfo> listHotKeys() =>
      RustLib.instance.api.crateApiWalletApiWalletListHotKeys(that: this);

  /// Return all saved unsigned PSBTs for this wallet, newest-first.
  Future<List<APIPsbtInfo>> listPsbts() =>
      RustLib.instance.api.crateApiWalletApiWalletListPsbts(that: this);

  /// Merge partial signatures from a signed PSBT into the stored one.
  ///
  /// The signed PSBT must refer to the same transaction (same inputs/outputs).
  /// Returns the updated info.
  APIPsbtInfo mergePsbt({
    required PlatformInt64 id,
    required String signedPsbtBase64,
  }) => RustLib.instance.api.crateApiWalletApiWalletMergePsbt(
    that: this,
    id: id,
    signedPsbtBase64: signedPsbtBase64,
  );

  /// Repropagate all existing explicit labels to their related entities.
  /// Useful after imports or migrations. Clears all auto labels first.
  void repropagateAllLabels() => RustLib.instance.api
      .crateApiWalletApiWalletRepropagateAllLabels(that: this);

  /// Force a full scan regardless of sync history (re-discovers all addresses).
  Future<void> rescan({required String electrumUrl}) => RustLib.instance.api
      .crateApiWalletApiWalletRescan(that: this, electrumUrl: electrumUrl);

  /// Reveal the stored seed phrase or xprv for a hot signing key.
  ///
  /// The SQLCipher layer already protects this data at rest; this function
  /// exposes it in plaintext for display purposes only. Call only when the
  /// user explicitly requests it and after showing an appropriate disclaimer.
  String revealHotKey({required String mfp}) => RustLib.instance.api
      .crateApiWalletApiWalletRevealHotKey(that: this, mfp: mfp);

  /// Reveal `count` new addresses for the given keychain beyond those already revealed,
  /// then persist the wallet. Returns the new total number of revealed addresses.
  int revealMoreAddresses({
    required APIKeychain keychain,
    required int count,
  }) => RustLib.instance.api.crateApiWalletApiWalletRevealMoreAddresses(
    that: this,
    keychain: keychain,
    count: count,
  );

  /// Persist a label for an address. Pass an empty string to remove it.
  /// Automatically propagates to related entities (transactions and UTXOs).
  /// Clearing an inherited (auto) label is a no-op.
  void setAddressLabel({required String address, required String label}) =>
      RustLib.instance.api.crateApiWalletApiWalletSetAddressLabel(
        that: this,
        address: address,
        label: label,
      );

  /// Persist a label for a coin (UTXO) by outpoint. Pass an empty string to remove it.
  /// Automatically propagates to related entities (transaction and address).
  /// Clearing an inherited (auto) label is a no-op.
  void setCoinLabel({
    required String txid,
    required int vout,
    required String label,
  }) => RustLib.instance.api.crateApiWalletApiWalletSetCoinLabel(
    that: this,
    txid: txid,
    vout: vout,
    label: label,
  );

  /// Store the Electrum URL so it can be used by detail queries (e.g. fetching
  /// unknown input transactions). Call this before sync if you want it available
  /// immediately without waiting for sync to complete.
  void setElectrumUrl({required String url}) => RustLib.instance.api
      .crateApiWalletApiWalletSetElectrumUrl(that: this, url: url);

  /// Persist a label for a key by master fingerprint. Pass an empty string to remove it.
  void setKeyLabel({required String mfp, required String label}) => RustLib
      .instance
      .api
      .crateApiWalletApiWalletSetKeyLabel(that: this, mfp: mfp, label: label);

  /// Persist a label for a spend path by rust_id. Pass an empty string to remove it.
  void setPathLabel({required int rustId, required String label}) =>
      RustLib.instance.api.crateApiWalletApiWalletSetPathLabel(
        that: this,
        rustId: rustId,
        label: label,
      );

  /// Set or clear the label for a saved PSBT. Pass an empty string to clear.
  APIPsbtInfo setPsbtLabel({
    required PlatformInt64 id,
    required String label,
  }) => RustLib.instance.api.crateApiWalletApiWalletSetPsbtLabel(
    that: this,
    id: id,
    label: label,
  );

  /// Persist a label for a transaction. Pass an empty string to remove it.
  /// Automatically propagates to related entities (addresses and UTXOs).
  /// Clearing an inherited (auto) label is a no-op.
  void setTxLabel({required String txid, required String label}) => RustLib
      .instance
      .api
      .crateApiWalletApiWalletSetTxLabel(that: this, txid: txid, label: label);

  /// Sign a stored PSBT using the hot key identified by `mfp`.
  ///
  /// Only the signer for the given master fingerprint is loaded, so BDK can
  /// never accidentally sign with a key the user did not intend. The PSBT is
  /// **never auto-finalized** (`try_finalize: false`) — the user explicitly
  /// controls finalization, which prevents premature finalization in multisig
  /// or complex Taproot setups where BDK might otherwise finalize on the first
  /// satisfied threshold.
  ///
  /// Returns the updated [`APIPsbtInfo`] with the partial signatures added.
  APIPsbtInfo signPsbtWithKey({
    required PlatformInt64 psbtId,
    required String mfp,
  }) => RustLib.instance.api.crateApiWalletApiWalletSignPsbtWithKey(
    that: this,
    psbtId: psbtId,
    mfp: mfp,
  );

  /// Store (or replace) the BTC price in `currency` at the time of a transaction.
  Future<void> storeFiatPrice({
    required String txid,
    required String currency,
    required double btcPrice,
  }) => RustLib.instance.api.crateApiWalletApiWalletStoreFiatPrice(
    that: this,
    txid: txid,
    currency: currency,
    btcPrice: btcPrice,
  );

  /// Sync with Electrum, persist, and update last_synced_at.
  ///
  /// Uses full_scan on first sync (last_synced_at is None) to discover all addresses
  /// up to the stop gap. Uses incremental sync on subsequent calls to only check
  /// already-revealed script pubkeys, which is much faster.
  Future<void> sync_({required String electrumUrl}) => RustLib.instance.api
      .crateApiWalletApiWalletSync(that: this, electrumUrl: electrumUrl);
}

@sealed
class SpendPathImpl extends RustOpaque implements SpendPath {
  // Not to be used by end users
  SpendPathImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  SpendPathImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_SpendPath,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_SpendPath,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_SpendPathPtr,
  );
}
